-- 003: početno stanje sa papira (AutostaklaSpisak.pdf). GENERISANO: tools/pocetno_stanje.py – ne menjati ručno.
-- PRAVILO: ponovljivo – INSERT OR IGNORE / WHERE NOT EXISTS.

-- Skladišta
INSERT OR IGNORE INTO skladiste (naziv, opis, redosled) VALUES ('1 Stalak', NULL, 1);
INSERT OR IGNORE INTO skladiste (naziv, opis, redosled) VALUES ('2 Stalak', NULL, 2);
INSERT OR IGNORE INTO skladiste (naziv, opis, redosled) VALUES ('Dvorište', 'pored garaže', 3);
INSERT OR IGNORE INTO skladiste (naziv, opis, redosled) VALUES ('Garaža', NULL, 4);

-- Police
INSERT OR IGNORE INTO polica (skladiste_id, naziv, opis, redosled) SELECT id, 'Polica 1', NULL, 1 FROM skladiste WHERE naziv = '1 Stalak';
INSERT OR IGNORE INTO polica (skladiste_id, naziv, opis, redosled) SELECT id, 'Polica 2', NULL, 2 FROM skladiste WHERE naziv = '1 Stalak';
INSERT OR IGNORE INTO polica (skladiste_id, naziv, opis, redosled) SELECT id, 'Polica 1', NULL, 1 FROM skladiste WHERE naziv = '2 Stalak';
INSERT OR IGNORE INTO polica (skladiste_id, naziv, opis, redosled) SELECT id, 'Polica 2', NULL, 2 FROM skladiste WHERE naziv = '2 Stalak';
INSERT OR IGNORE INTO polica (skladiste_id, naziv, opis, redosled) SELECT id, 'I deo', NULL, 1 FROM skladiste WHERE naziv = 'Dvorište';
INSERT OR IGNORE INTO polica (skladiste_id, naziv, opis, redosled) SELECT id, 'II deo', NULL, 2 FROM skladiste WHERE naziv = 'Dvorište';
INSERT OR IGNORE INTO polica (skladiste_id, naziv, opis, redosled) SELECT id, 'Polica 1', NULL, 1 FROM skladiste WHERE naziv = 'Garaža';

